import unittest
from app import normalize_slug

class NormalizeSlugTest(unittest.TestCase):
    def test_normalizes_words_and_preserves_digits(self):
        for value, expected in [("  Hello   World  ", "hello-world"), ("A1 B2", "a1-b2"), ("One\tTwo\nThree", "one-two-three"), ("MiXeD", "mixed")]:
            with self.subTest(value=value):
                self.assertEqual(expected, normalize_slug(value))

    def test_empty_and_whitespace(self):
        for value in ("", " ", "\t\n"):
            self.assertEqual("", normalize_slug(value))

    def test_invalid_input(self):
        for value in (None, 123):
            with self.assertRaises((TypeError, AttributeError)):
                normalize_slug(value)

if __name__ == "__main__":
    unittest.main()

import unittest
from app import positive_total

class PositiveTotalTest(unittest.TestCase):
    def test_sums_only_positive_values(self):
        for values, expected in [([-3, 0, 5, 7], 12), ([1, 2, 3], 6), ([-4, -1, 0], 0), ([10**20, 1], 10**20 + 1), ([], 0)]:
            with self.subTest(values=values):
                before = list(values)
                self.assertEqual(expected, positive_total(values))
                self.assertEqual(before, values)

    def test_invalid_input(self):
        for values in (None, ["1"], [None]):
            with self.assertRaises(TypeError):
                positive_total(values)

if __name__ == "__main__":
    unittest.main()
